/**
 * palette.gpl + scripts/art/tokens.mjs → src/assets/_meta/tokens.json.
 *
 * Runtime code (src/ui/tokens.ts) reads the JSON; the art scripts read the
 * same map through palette.mjs. One generated file, two consumers, zero drift.
 *
 *   node scripts/generate-tokens.mjs      (also runs inside `pnpm art`)
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { readGpl, toHex } from './art/quantize.mjs';
import { MOTION_TOKENS, TOKEN_INDEX } from './art/tokens.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const meta = resolve(here, '../src/assets/_meta');

const palette = readGpl(readFileSync(join(meta, 'palette.gpl'), 'utf8'));
const tokens = {};
for (const [name, index] of Object.entries(TOKEN_INDEX)) {
  if (!palette[index]) throw new Error(`token "${name}" points at palette index ${index}, but the palette has ${palette.length} entries`);
  tokens[name] = toHex(palette[index]);
}

writeFileSync(
  join(meta, 'tokens.json'),
  `${JSON.stringify(
    {
      $comment: 'Generated by scripts/generate-tokens.mjs from palette.gpl + scripts/art/tokens.mjs. Do not edit; change the token map and rerun pnpm art.',
      palette: palette.map(toHex),
      tokens,
      motion: MOTION_TOKENS,
    },
    null,
    2,
  )}\n`,
);
console.log(`✓ tokens.json — ${Object.keys(tokens).length} colour tokens over ${palette.length} palette colours, ${Object.keys(MOTION_TOKENS).length} motion tokens`);
